    ctlPhone: [["◎", "左摇杆——移动"], ["⤒", "跳跃按钮"], ["⚔", "攻击和技能按钮"], ["▦", "底部栏：游戏、角色、宠物、兑换"], ["☰", "右上角菜单"]],
